defmodule Vxpipe.MCP.SessionTLSFixture do
  @moduledoc false

  # Initialize a session, then hold its reconnecting GET's TLS handshake.
  # Certificates exist only in memory and are generated by OTP's test-data API.
  def initialize_then_hold_get(listener, observer) do
    certificate = [digest: :sha256, key: {:rsa, 2_048, 65_537}]
    tls = :public_key.pkix_test_data(%{root: certificate, peer: certificate})

    initialize = accept(listener, tls)
    request = read_request(initialize, "")
    "initialize" = Map.fetch!(request, "method")
    :ok = :ssl.send(initialize, response(request))
    :ssl.close(initialize)

    stream = accept(listener, tls)
    :get = read_request(stream, "")
    chunk = ": ready\nretry: 10\n\n"

    :ok =
      :ssl.send(stream, [
        "HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nTransfer-Encoding: chunked\r\n\r\n",
        Integer.to_string(byte_size(chunk), 16),
        "\r\n",
        chunk,
        "\r\n"
      ])

    initialized = accept(listener, tls)
    notification = read_request(initialized, "")
    "notifications/initialized" = Map.fetch!(notification, "method")
    :ok = :ssl.send(initialized, response(notification))
    :ssl.close(initialized)
    send(observer, :tls_session_initialized)
    receive do: (:stall_get -> :ok)
    :ok = :ssl.send(stream, "0\r\n\r\n")
    :ssl.close(stream)

    {:ok, peer} = :gen_tcp.accept(listener)
    {:ok, <<22, _client_hello::binary>>} = :gen_tcp.recv(peer, 0, 2_000)
    send(observer, :get_tls_connect_blocked)
    send(observer, {:get_tls_peer_closed, await_close(peer, now() + 5_000)})
  end

  defp accept(listener, tls) do
    {:ok, tcp} = :gen_tcp.accept(listener)
    {:ok, socket} = :ssl.handshake(tcp, tls ++ [active: false, verify: :verify_none], 2_000)
    socket
  end

  defp read_request(socket, buffer) do
    case String.split(buffer, "\r\n\r\n", parts: 2) do
      [headers, body] ->
        if String.starts_with?(headers, "GET ") do
          :get
        else
          [_, length] = Regex.run(~r/content-length: (\d+)/i, headers)
          decode_body(socket, body, String.to_integer(length))
        end

      [_incomplete] ->
        {:ok, next} = :ssl.recv(socket, 0, 2_000)
        read_request(socket, buffer <> next)
    end
  end

  defp decode_body(_socket, body, length) when byte_size(body) >= length,
    do: JSON.decode!(binary_part(body, 0, length))

  defp decode_body(socket, body, length) do
    {:ok, next} = :ssl.recv(socket, 0, 2_000)
    decode_body(socket, body <> next, length)
  end

  defp response(%{"method" => "initialize", "id" => id}) do
    body =
      JSON.encode!(%{
        "jsonrpc" => "2.0",
        "id" => id,
        "result" => %{
          "protocolVersion" => "2025-11-25",
          "capabilities" => %{"tools" => %{}},
          "serverInfo" => %{"name" => "TLS fixture", "version" => "1"}
        }
      })

    "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\n" <>
      "Mcp-Session-Id: tls-fixture-session\r\nContent-Length: #{byte_size(body)}\r\n\r\n" <> body
  end

  defp response(%{"method" => "notifications/initialized"}),
    do: "HTTP/1.1 202 Accepted\r\nContent-Length: 0\r\n\r\n"

  defp await_close(socket, deadline) do
    case :gen_tcp.recv(socket, 0, max(deadline - now(), 0)) do
      {:ok, _tls_alerts} -> await_close(socket, deadline)
      closed -> closed
    end
  end

  defp now, do: System.monotonic_time(:millisecond)
end
